import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_source = r"""
#include <torch/extension.h>

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);
"""

_cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAException.h>
#include <cstdint>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
constexpr int ROWS_PER_BLOCK = 16;
constexpr int SPLIT_K_PARTS = 8;

__global__ void matvec_splitk_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ partial,
    int64_t M,
    int64_t K,
    int64_t chunk_k
) {
    constexpr int TILE_K = 1024;
    constexpr int THREADS = 256;
    constexpr int WARPS = THREADS / 32;
    constexpr int VALUES_PER_THREAD = 4;

    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int64_t row_base =
        static_cast<int64_t>(blockIdx.x) * ROWS_PER_BLOCK;
    const int split = static_cast<int>(blockIdx.y);
    const int64_t split_begin =
        min(K, static_cast<int64_t>(split) * chunk_k);
    const int64_t split_end =
        min(K, split_begin + chunk_k);

    __shared__ float b_tile[TILE_K];
    __shared__ float warp_sums[ROWS_PER_BLOCK][WARPS];
    float sums[ROWS_PER_BLOCK] = {};

    for (int64_t k_base = split_begin; k_base < split_end; k_base += TILE_K) {
        const int64_t k0 =
            k_base + static_cast<int64_t>(tid) * VALUES_PER_THREAD;

        if (k0 + 3 < split_end) {
            const float4 bv =
                *reinterpret_cast<const float4*>(B + k0);
            b_tile[tid * 4 + 0] = bv.x;
            b_tile[tid * 4 + 1] = bv.y;
            b_tile[tid * 4 + 2] = bv.z;
            b_tile[tid * 4 + 3] = bv.w;
        } else {
            #pragma unroll
            for (int q = 0; q < VALUES_PER_THREAD; ++q) {
                const int64_t k = k0 + q;
                b_tile[tid * 4 + q] =
                    (k < split_end) ? B[k] : 0.0f;
            }
        }
        __syncthreads();

        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
            const int64_t row = row_base + static_cast<int64_t>(r);
            if (row < M) {
                const float* row_ptr = A + row * K;
                if (k0 + 3 < split_end &&
                    (reinterpret_cast<uintptr_t>(row_ptr + k0) & 15u) == 0) {
                    const float4 av =
                        *reinterpret_cast<const float4*>(row_ptr + k0);
                    sums[r] += av.x * b_tile[tid * 4 + 0];
                    sums[r] += av.y * b_tile[tid * 4 + 1];
                    sums[r] += av.z * b_tile[tid * 4 + 2];
                    sums[r] += av.w * b_tile[tid * 4 + 3];
                } else {
                    #pragma unroll
                    for (int q = 0; q < VALUES_PER_THREAD; ++q) {
                        const int64_t k = k0 + q;
                        if (k < split_end) {
                            sums[r] += row_ptr[k] * b_tile[tid * 4 + q];
                        }
                    }
                }
            }
        }
        __syncthreads();
    }

    const unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sums[r] += __shfl_down_sync(mask, sums[r], offset);
        }
        if (lane == 0) {
            warp_sums[r][warp] = sums[r];
        }
    }
    __syncthreads();

    if (tid == 0) {
        float* partial_ptr = partial +
            static_cast<int64_t>(split) * M;
        #pragma unroll
        for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
            const int64_t row = row_base + static_cast<int64_t>(r);
            if (row < M) {
                float result = 0.0f;
                #pragma unroll
                for (int w = 0; w < WARPS; ++w) {
                    result += warp_sums[r][w];
                }
                partial_ptr[row] = result;
            }
        }
    }
}

__global__ void reduce_splitk_kernel(
    const float* __restrict__ partial,
    float* __restrict__ C,
    int64_t M,
    int splits
) {
    const int64_t row =
        static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (row < M) {
        float result = 0.0f;
        #pragma unroll
        for (int s = 0; s < SPLIT_K_PARTS; ++s) {
            if (s < splits) {
                result += partial[static_cast<int64_t>(s) * M + row];
            }
        }
        C[row] = result;
    }
}

torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2, "A must have shape (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.device() == B.device(), "A and B must be on the same CUDA device");

    c10::cuda::CUDAGuard device_guard(A.device());
    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();
    const int64_t M = A_contiguous.size(0);
    const int64_t K = A_contiguous.size(1);
    auto C = torch::empty({M, 1}, A_contiguous.options());

    const int splits = K > 0
        ? min(SPLIT_K_PARTS, static_cast<int>((K + 131071) / 131072))
        : 1;
    const int64_t chunk_k = K > 0
        ? (K + splits - 1) / splits
        : 0;
    auto partial = torch::empty({splits, M}, A_contiguous.options());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream(
        A_contiguous.get_device()
    ).stream();

    const int64_t block_count =
        M > 0 ? (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK : 1;
    const dim3 grid(
        static_cast<unsigned int>(block_count),
        static_cast<unsigned int>(splits),
        1
    );
    const dim3 block(256);
    matvec_splitk_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        partial.data_ptr<float>(),
        M,
        K,
        chunk_k
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    const int reduction_blocks =
        M > 0 ? static_cast<int>((M + 255) / 256) : 1;
    reduce_splitk_kernel<<<reduction_blocks, 256, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        splits
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_matvec_cuda = load_inline(
    name="matvec_cuda_extension_debug_v2",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    functions=["matvec_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matvec_cuda.matvec_cuda(A, B)

