    const int64_t K = A_contiguous.size(1);
    auto C = torch::empty({M, 1}, A_contiguous.options());

    const int splits = K > 0
        ? min(SPLIT_K_PARTS, static_cast<int>((K + 131071) / 131072))
        : 1;
    const int64_t chunk_k = K > 0
        ? (K + splits - 1) / splits
        : 0;
    auto partial = torch::empty({splits, M}, A_contiguous.options());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream(
        A_contiguous.get_device()
    ).stream();

    const int64_t block_count =
        M > 0 ? (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK : 1;
    const dim3 grid(
        static_cast<unsigned int>(block_count),
        static_cast<unsigned int>(splits),
        1
    );
    const dim3 block(256);
    matvec_splitk_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        partial.data_ptr<float>(),
        M,
        K,
        chunk_k
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    const int reduction_blocks =
        M > 0 ? static_cast<int>((M + 255) / 256) : 1;
    reduce_splitk_kernel<<<reduction_blocks, 256, 0, stream>>>(
        partial.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        splits
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
